<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { CefEvent,RpcEvent,type BalanceView,type BankTransactionView,type InventoryView,type JobAssignmentView,type JobProgressView,type JobStepResult,type QuestView,type VehicleActionView,type VehicleView } from '@eclipse/shared';
import { rpc } from '../core/rpc';import { toClient } from '../core/bridge';import FamilyPanel from '../components/FamilyPanel.vue';import PropertyPanel from '../components/PropertyPanel.vue';import BusinessPanel from '../components/BusinessPanel.vue';import MarketplacePanel from '../components/MarketplacePanel.vue';import FuelPanel from '../components/FuelPanel.vue';import PublicServicesPanel from '../components/PublicServicesPanel.vue';import DocumentsPanel from '../components/DocumentsPanel.vue';import CriminalPanel from '../components/CriminalPanel.vue';import ClothingPanel from '../components/ClothingPanel.vue';import GroomingPanel from '../components/GroomingPanel.vue';import TuningPanel from '../components/TuningPanel.vue';
type Tab='bank'|'inventory'|'jobs'|'quests'|'family'|'property'|'business'|'market'|'fuel'|'services'|'documents'|'criminal'|'clothing'|'grooming'|'tuning'|'garage';const tab=ref<Tab>('bank'),balance=ref<BalanceView|null>(null),history=ref<BankTransactionView[]>([]),inventory=ref<InventoryView|null>(null),jobs=ref<JobProgressView[]>([]),activeJob=ref<JobAssignmentView|null>(null),quests=ref<QuestView[]>([]),vehicles=ref<VehicleView[]>([]),amount=ref(''),busy=ref(false),error=ref('');
const load=async()=>{const[b,h,i,j,a,q,v]=await Promise.all([rpc<BalanceView>(RpcEvent.EconomyBalance),rpc<BankTransactionView[]>(RpcEvent.EconomyHistory,{limit:30}),rpc<InventoryView>(RpcEvent.InventoryGet),rpc<JobProgressView[]>(RpcEvent.JobProgress),rpc<JobAssignmentView|null>(RpcEvent.JobActive),rpc<QuestView[]>(RpcEvent.QuestList),rpc<VehicleView[]>(RpcEvent.VehicleList)]);if(b.ok)balance.value=b.data;if(h.ok)history.value=h.data;if(i.ok)inventory.value=i.data;if(j.ok)jobs.value=j.data;if(a.ok)activeJob.value=a.data;if(q.ok)quests.value=q.data;if(v.ok)vehicles.value=v.data;};const money=(v:string|undefined)=>Number(v??0).toLocaleString('ru-RU',{maximumFractionDigits:2});const bankAction=async(event:string)=>{busy.value=true;const r=await rpc<BalanceView>(event,{amount:amount.value});busy.value=false;if(r.ok){balance.value=r.data;amount.value='';await load();}else error.value=r.code;};const startJob=async(jobKey:string)=>{const r=await rpc<JobAssignmentView>(RpcEvent.JobStart,{jobKey});if(r.ok)activeJob.value=r.data;else error.value=r.code;};const completeJobStep=async()=>{const r=await rpc<JobStepResult>(RpcEvent.JobCompleteStep);if(r.ok){activeJob.value=r.data.assignment;if(r.data.completed)await load();}else error.value=r.code;};const cancelJob=async()=>{const r=await rpc<{cancelled:boolean}>(RpcEvent.JobCancel);if(r.ok)activeJob.value=null;else error.value=r.code;};const claimQuest=async(key:string)=>{const r=await rpc<QuestView>(RpcEvent.QuestClaim,{key});if(r.ok)await load();else error.value=r.code;};const vehicleAction=async(event:string,car:VehicleView)=>{const r=await rpc<VehicleActionView|VehicleView>(event,{vehicleId:car.id});if(r.ok)await load();else error.value=r.code;};const close=()=>toClient(CefEvent.OverlayClose);onMounted(()=>void load());
</script>
<template><div class="tablet-shell e-interactive"><section class="tablet"><aside class="sidebar"><div class="logo">E<span>CLIPSE</span></div><button v-for="x in ([['bank','Банк'],['inventory','Инвентарь'],['jobs','Работы'],['quests','Задания'],['family','Семья'],['property','Недвижимость'],['business','Бизнес'],['market','V‑Market'],['fuel','АЗС'],['services','Организация'],['documents','Документы'],['criminal','Криминал'],['clothing','Одежда'],['grooming','Внешность'],['tuning','Тюнинг'],['garage','Гараж']] as const)" :key="x[0]" :class="{active:tab===x[0]}" @click="tab=x[0]">{{x[1]}}</button><button class="close" @click="close">Закрыть</button></aside><main class="main"><header><div><small>ПЛАНШЕТ</small><h1>{{ {bank:'Финансы',inventory:'Инвентарь',jobs:'Работы',quests:'Задания',family:'Семья',property:'Недвижимость',business:'Бизнес',market:'V‑Market',fuel:'АЗС',services:'Организация / MDT',documents:'Документы и лицензии',criminal:'Криминальная организация',clothing:'Одежда и гардероб',grooming:'Барбершоп и тату',tuning:'Тюнинг транспорта',garage:'Транспорт'}[tab] }}</h1></div><button @click="load">Обновить</button></header><p v-if="error" class="error">{{error}}</p>
<template v-if="tab==='bank'"><div class="cards"><article><span>Наличные</span><strong>${{money(balance?.cash)}}</strong></article><article><span>Банк</span><strong>${{money(balance?.bank)}}</strong></article></div><div class="bank-form"><input v-model="amount" placeholder="Сумма"><button @click="bankAction(RpcEvent.EconomyDeposit)">Внести</button><button @click="bankAction(RpcEvent.EconomyWithdraw)">Снять</button></div><div class="list"><article v-for="tx in history" :key="tx.id"><div><b>{{tx.description||tx.kind}}</b><small>{{new Date(tx.createdAt).toLocaleString('ru-RU')}}</small></div><strong>${{money(tx.amount)}}</strong></article></div></template>
<template v-else-if="tab==='inventory'"><div class="inventory-head">Вес {{inventory?.usedWeight??'0'}} / {{inventory?.capacityWeight??'0'}} кг</div><div class="items"><article v-for="item in inventory?.items" :key="item.id"><strong>{{item.name}}</strong><span>{{item.category}} · слот {{item.slot+1}}</span><b>×{{item.quantity}}</b></article></div></template>
<template v-else-if="tab==='jobs'"><section v-if="activeJob" class="active-job"><div><h2>{{activeJob.name}}</h2><p>Точка {{activeJob.step}}/{{activeJob.totalSteps}} · ${{money(activeJob.rewardCash)}}</p></div><div><button @click="completeJobStep">Я на точке</button><button @click="cancelJob">Отменить</button></div></section><div class="jobs"><article v-for="job in jobs" :key="job.jobKey"><strong>{{job.name}}</strong><span>Уровень {{job.level}} · {{job.experience}} XP</span><button :disabled="!!activeJob" @click="startJob(job.jobKey)">Начать</button></article></div></template>
<template v-else-if="tab==='quests'"><div class="list"><article v-for="q in quests" :key="q.key"><div><b>{{q.title}}</b><small>{{q.progress}} / {{q.target}}</small></div><button v-if="q.completed&&!q.claimed" @click="claimQuest(q.key)">Забрать</button></article></div></template>
<FamilyPanel v-else-if="tab==='family'"/><PropertyPanel v-else-if="tab==='property'"/><BusinessPanel v-else-if="tab==='business'"/><MarketplacePanel v-else-if="tab==='market'"/><FuelPanel v-else-if="tab==='fuel'"/><PublicServicesPanel v-else-if="tab==='services'"/><DocumentsPanel v-else-if="tab==='documents'"/><CriminalPanel v-else-if="tab==='criminal'"/><ClothingPanel v-else-if="tab==='clothing'"/><GroomingPanel v-else-if="tab==='grooming'"/><TuningPanel v-else-if="tab==='tuning'"/>
<template v-else><div class="vehicles"><article v-for="car in vehicles" :key="car.id"><div><strong>{{car.model}}</strong><span>VIN {{car.vin}}</span></div><div><span>{{car.fuel}}% · {{car.mileage}} км</span></div><div><button v-if="!car.spawned" :disabled="car.impounded" @click="vehicleAction(RpcEvent.VehicleSpawn,car)">Доставить</button><button v-else @click="vehicleAction(RpcEvent.VehicleStore,car)">В гараж</button><button @click="vehicleAction(RpcEvent.VehicleToggleLock,car)">{{car.locked?'Открыть':'Закрыть'}}</button></div></article></div></template></main></section></div></template>
<style scoped>.tablet-shell{position:absolute;inset:0;display:grid;place-items:center;background:rgba(3,5,9,.42);backdrop-filter:blur(6px)}.tablet{width:min(1180px,90vw);height:min(760px,86vh);display:grid;grid-template-columns:210px 1fr;background:rgba(10,12,18,.97);border:1px solid var(--e-border);border-radius:26px;overflow:hidden}.sidebar{display:flex;flex-direction:column;gap:4px;padding:16px 14px;border-right:1px solid var(--e-border);overflow:auto}.logo{font-size:22px;font-weight:900;margin:2px 8px 12px;color:var(--e-accent)}.logo span{color:var(--e-text-primary)}.sidebar button,.main button{padding:8px 12px;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--e-text-secondary);cursor:pointer}.sidebar button.active,.main button{background:var(--e-surface-2);border-color:var(--e-border);color:var(--e-text-primary)}.sidebar .close{margin-top:auto;color:#ff8a8a}.main{overflow:auto;padding:26px 30px}.main header{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.main h1{margin:3px 0}.cards,.jobs,.items{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.cards article,.jobs article,.items article,.vehicles article{padding:14px;border:1px solid var(--e-border);border-radius:12px;background:var(--e-surface-1)}.bank-form,.active-job{display:flex;gap:8px;margin:15px 0}.bank-form input{flex:1;padding:10px;background:var(--e-surface-1);border:1px solid var(--e-border);color:var(--e-text-primary)}.list article,.vehicles article{display:flex;justify-content:space-between;align-items:center;gap:12px;border-bottom:1px solid var(--e-border);padding:12px}.list article div,.items article,.jobs article{display:flex;flex-direction:column;gap:5px}.main small,.main span{color:var(--e-text-muted)}.error{color:#ff8585}.inventory-head{margin-bottom:12px}</style>